CREATE POLICY "infiniti_select_own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'infiniti' AND owner = auth.uid());
CREATE POLICY "infiniti_insert_own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'infiniti' AND owner = auth.uid() AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "infiniti_update_own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'infiniti' AND owner = auth.uid()) WITH CHECK (bucket_id = 'infiniti' AND owner = auth.uid());
CREATE POLICY "infiniti_delete_own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'infiniti' AND owner = auth.uid());